const items = $input.all();
return items.map(item => {
  const data = item.json;
  // Sanitização simples de PII (anonimização básica para LGPD)
  let sanitizedComment = (data.comment || '')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF REMOVIDO]')
    .replace(/\b(?:\+?55\s?)?(?:\(?\d{2}\)?\s?)?\d{4,5}-?\d{4}\b/g, '[TELEFONE REMOVIDO]');

  return {
    json: {
      ticket_id: data.ticket_id || `TCK-${Date.now()}`,
      customer_id: data.customer_id || 'ANONYMOUS',
      order_id: data.order_id || 'N/A',
      original_comment: data.comment,
      sanitized_comment: sanitizedComment,
      rating: Number(data.rating) || 0,
      received_at: new Date().toISOString()
    }
  };
});

