const response = $input.first().json;
const preProcessed = $('Sanitize & Pre-process PII').first().json;

let parsedLLM = {};
try {
  parsedLLM = JSON.parse(response.choices[0].message.content);
} catch (e) {
  parsedLLM = {
    categoria: 'Erro de Parsing',
    sentimento: 'Neutro',
    nivel_urgencia: 3,
    risco_churn: 'Médio',
    resumo_executivo: 'Falha no processamento da LLM',
    acao_sugerida: 'Triagem manual requerida'
  };
}

return {
  json: {
    ...preProcessed,
    ...parsedLLM,
    is_critical: parsedLLM.nivel_urgencia >= 4 || parsedLLM.risco_churn === 'Alto' || preProcessed.rating <= 2
  }
};

